import{_ as a,o as e,c as r,a5 as l}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"硅酸盐 · 架状（网状）","description":"","frontmatter":{"title":"硅酸盐 · 架状（网状）","mineralGroup":"silicates-framework"},"headers":[],"relativePath":"zh/classification/mineral-groups/silicates-framework.md","filePath":"zh/classification/mineral-groups/silicates-framework.md","lastUpdated":1790876393000}'),i={name:"zh/classification/mineral-groups/silicates-framework.md"};function d(o,t,s,n,c,h){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="硅酸盐-·-架状-网状" tabindex="-1">硅酸盐 · 架状（网状） <a class="header-anchor" href="#硅酸盐-·-架状-网状" aria-label="Permalink to &quot;硅酸盐 · 架状（网状）&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>架状硅酸盐 SiO₂ 与 Al₂O₃ 摩尔比约为 3:1–6:1。最重要的宝石 矿物族是长石族（月光石 / 拉长石 / 太阳石 / 天河石 / 拉布拉多 拉长石）；次要族为沸石族（不常作宝石）。长石占地球地壳矿物 总重量的约 60%。</p><h2 id="化学式类型" tabindex="-1">化学式类型 <a class="header-anchor" href="#化学式类型" aria-label="Permalink to &quot;化学式类型&quot;">​</a></h2><p>M(Al,Si)₄O₈</p><h2 id="结构" tabindex="-1">结构 <a class="header-anchor" href="#结构" aria-label="Permalink to &quot;结构&quot;">​</a></h2><p>[SiO₄]⁴⁻ 四面体每个顶角与其他四面体共享，形成三维无限架状 结构。长石族中 Si⁴⁺ 与 Al³⁺ 在四面体位置有序替代，碱/碱土金 属阳离子充填结构空隙。Si/Al 比与阳离子类型决定矿物种属。</p><h2 id="代表性宝石" tabindex="-1">代表性宝石 <a class="header-anchor" href="#代表性宝石" aria-label="Permalink to &quot;代表性宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>化学式</th><th>亚族</th></tr></thead><tbody><tr><td>Moonstone / 月光石</td><td>(K,Na)AlSi₃O₈</td><td>orthoclase</td></tr><tr><td>Labradorite / 拉长石</td><td>(Ca,Na)(Si,Al)₄O₈</td><td>plagioclase</td></tr><tr><td>Sunstone / 日光石</td><td>(Na,Ca)(Si,Al)₄O₈ + Cu/Fe</td><td>plagioclase</td></tr><tr><td>Amazonite / 天河石</td><td>KAlSi₃O₈</td><td>microcline</td></tr><tr><td>Spectrolite / 光谱石</td><td>(Ca,Na)(Si,Al)₄O₈</td><td>plagioclase</td></tr><tr><td>Orthoclase / 正长石</td><td>KAlSi₃O₈</td><td>orthoclase</td></tr></tbody></table><p><em>详见<a href="./intro.html">矿物组总览</a>。</em></p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://elearning-samples.gia.edu/Gem_Identification/Page5.html" target="_blank" rel="noreferrer">GIA：宝石的矿物种、品种与矿物组</a><span>矿物种、宝石品种与矿物组的层级关系</span><small>打开来源 ↗</small></li><li><a href="https://www.mindat.org/" target="_blank" rel="noreferrer">Mindat 矿物数据库</a><span>矿物名称、化学组成与分类检索</span><small>打开来源 ↗</small></li></ul></aside>',11)])])}const f=a(i,[["render",d]]);export{p as __pageData,f as default};
